// sketch.ino — ESP32: Wi-Fi + кнопка GPIO13 -> TCP "CMD_SHUTDOWN"
#include <WiFi.h>
#include <EEPROM.h>

const char* SSID     = "DIR-615T-0DBC";
const char* PASSWORD = "23233010";
const char* PC_IP    = "192.168.0.152";   // <-- IP твоего ПК в этой сети
const uint16_t PORT  = 4444;

const uint8_t BTN = 13;

void setup() {
  pinMode(BTN, INPUT_PULLUP);   // кнопка между GPIO13 и GND
  Serial.begin(115200);

  WiFi.mode(WIFI_STA);
  WiFi.begin(SSID, PASSWORD);
  Serial.print("Подключаюсь");
  while (WiFi.status() != WL_CONNECTED) {
    delay(300);
    Serial.print(".");
  }
  Serial.printf("\nГотов. IP платы: %s\n", WiFi.localIP().toString().c_str());
}

void sendShutdown() {
  WiFiClient client;
  if (!client.connect(PC_IP, PORT)) {
    Serial.println("ПК недоступен");
    return;
  }
  client.print("CMD_SHUTDOWN\n");
  client.stop();
  Serial.println("Команда отправлена");
}

void loop() {
  if (digitalRead(BTN) == LOW) {
    delay(30);                  // антидребезг
    if (digitalRead(BTN) == LOW) {
      if (WiFi.status() != WL_CONNECTED) {   // отвалилось — переподключаемся
        WiFi.disconnect();
        WiFi.begin(SSID, PASSWORD);
        delay(2000);
      } else {
        sendShutdown();
      }
      while (digitalRead(BTN) == LOW) delay(10);  // ждём отпускания
    }
  }
}
